'use strict';
const $=s=>document.querySelector(s);
const moments=[{"key":"website","time":"WEBSITE DESIGN & DEVELOPMENT","title":"Your business.<br>A strong online presence.","description":"Present your company with a website designed around your brand, services and the people you want to reach.","before":{"client":["Your brand and goals","The foundation of your website"],"team":["A professional website","Clear content and useful features"],"owner":["Design and development","From initial concept to launch"],"record":["Define your requirements","Agree the purpose and priorities"]},"after":{"client":["A clear online presence","Your business, presented with care"],"team":["A complete website","Designed for mobile and desktop"],"owner":["Delivery and support","Development, testing and launch"],"record":["Review your project outline","Confirm the pages and features"]},"views":{"owner":["Represent your business with confidence.","Your website should help prospective clients understand your company, the services you provide and why they should contact you. We organise the content and design around your brand and the audience you serve.","Your business goals guide the design and development."],"team":["A complete, considered website.","We develop the agreed service pages, navigation and contact forms, with layouts for mobile and desktop. The project includes functional testing, launch preparation and a defined approach to hosting and maintenance.","The pages, features and support requirements are confirmed with you."],"client":["A clear path from concept to launch.","We establish your requirements, prepare the design and develop the approved website. You review progress at agreed stages, followed by testing and final approval before publication.","You remain involved in the decisions that shape your website."]},"steps":[["Discovery and planning","We review your brand, services and target audience, then define the website’s pages and features."],["Design and development","We create the visual design and develop the agreed website, with opportunities for your review."],["Testing and launch","We check the website across screen sizes, test its functions and prepare it for your approval and launch."]]},{"key":"redesign","time":"WEBSITE REVIEW & IMPROVEMENT","title":"Your website.<br>Aligned with your business.","description":"Strengthen your existing website through a focused review of its design, content and how visitors use it.","before":{"client":["Your current objectives","What your website needs to support"],"team":["Your existing website","Design, content and functionality"],"owner":["Review and improvement","Recommendations based on your site"],"record":["Set the priorities","Identify the changes that matter"]},"after":{"client":["A stronger presentation","Reflects your business today"],"team":["An improved experience","Clearer pages and navigation"],"owner":["Focused development","Agreed changes, carefully tested"],"record":["Review before release","Approve the updated website"]},"views":{"owner":["Bring your website into line with your goals.","As your business develops, your website should reflect its services, capabilities and identity. We assess where the current experience falls short and recommend changes that address those gaps.","The review determines whether targeted improvements or a rebuild is appropriate."],"team":["Improve the details that shape the experience.","The agreed work may include page design, content structure, mobile layouts, navigation and contact forms. We assess existing features and connections before deciding how to update or retain them.","Recommendations are based on your current website and project requirements."],"client":["Review, refine and release with confidence.","We review the existing site with you, define the improvements and develop the updated experience. The changes are tested and presented for your approval before the live website is updated.","Content and existing connections are considered as part of the transition."]},"steps":[["Website assessment","We examine the current design, content, navigation and functionality against your business objectives."],["Improvement plan","We agree the priorities and develop the approved changes, retaining useful elements where appropriate."],["Validation and release","We test the updated pages and features, review them with you and coordinate the release."]]},{"key":"digital","time":"CUSTOM SOFTWARE & DIGITAL TRANSFORMATION","title":"Your processes.<br>Connected through software.","description":"Develop digital systems around your business requirements, connecting information and reducing repeated manual work.","before":{"client":["Your business processes","Where information and work connect"],"team":["Your systems and tools","What to retain, connect or develop"],"owner":["Software development","Requirements, design and delivery"],"record":["Define the project","Priorities and a phased approach"]},"after":{"client":["A defined digital direction","Aligned with management priorities"],"team":["Purpose-built software","Features shaped by your processes"],"owner":["Phased development","Working software reviewed with you"],"record":["Validate with your team","Confirm readiness before rollout"]},"views":{"owner":["Make information easier to use.","We work with owners and management teams to identify where digital systems would support the business. The focus is on clearer information, fewer repeated tasks and processes that are easier to manage.","Each project starts with your objectives and existing ways of working."],"team":["Software designed around your requirements.","Depending on the agreed project, we develop management dashboards, online forms, customer portals or connections between existing systems. Data access and system limitations are considered during planning.","Features and integrations are assessed before they are included in the solution."],"client":["Develop in stages, with clear review points.","We document the requirements, design the solution and develop it in agreed stages. Your team reviews working features, tests them against real tasks and prepares for introduction with supporting guidance.","The rollout and ongoing support arrangements are defined with your team."]},"steps":[["Understand the requirements","We review your processes, information and existing tools to define what the software must achieve."],["Design and develop","We plan the solution and build the agreed features in stages, with regular progress reviews."],["Validate and introduce","We test the software with your team, prepare user guidance and coordinate the agreed rollout."]]}];
const plans={"website":{"title":"Website development","items":["Define the audience, content, pages and required features.","Design and develop the website around your brand.","Test, review and prepare the approved website for launch."],"measure":"Review the content, mobile and desktop layouts, navigation and forms against the agreed requirements.","needs":"Your company profile, brand assets, services, target audience and website objectives."},"redesign":{"title":"Website improvement","items":["Assess the existing website against your current objectives.","Agree and develop the priority improvements.","Validate the updated content and functionality before release."],"measure":"Check the revised pages and features against the improvement plan, including existing links and connections.","needs":"Your website address, current challenges, required features and content you wish to retain."},"digital":{"title":"Digital transformation","items":["Review current processes, systems and information needs.","Define the software requirements and development stages.","Develop, test and introduce the solution with your team."],"measure":"Validate each stage against the documented requirements and representative tasks performed by your team.","needs":"Your business objectives, current tools, process examples and the management team’s priorities."}};
let current=0,person='owner',connected=false;
function updateNodes(){const nodes=moments[current][connected?'after':'before'];Object.entries(nodes).forEach(([key,values])=>{$('#node-'+key).textContent=values[0];$('#sub-'+key).textContent=values[1]})}
function showPerspective(p){if(!['owner','team','client'].includes(p))return;person=p;const v=moments[current].views[p];$('#perspective-content').innerHTML=`<h2>${v[0]}</h2><p>${v[1]}</p><div class="human-note"><span aria-hidden="true">◈</span>${v[2]}</div>`;document.querySelectorAll('[data-person]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.person===p)))}
function chooseMoment(i){if(!Number.isInteger(i)||i<0||i>=moments.length)return;current=i;connected=false;const m=moments[i];$('#field').classList.remove('is-connected');$('.moment-content').hidden=false;$('#outcome').hidden=true;$('#steps-panel').hidden=true;$('#view-steps').setAttribute('aria-expanded','false');$('#moment-time').textContent=m.time;$('#moment-title').innerHTML=m.title;$('#moment-description').textContent=m.description;$('#stage-label').textContent='01 / YOUR STARTING POINT';$('#legend-text').textContent='Explore the service, deliverables and process.';document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scenario)===i)));updateNodes();showPerspective('owner');$('#priority').value=m.key;updatePlan()}
function connect(){connected=true;$('#field').classList.add('is-connected');$('.moment-content').hidden=true;$('#outcome').hidden=false;$('#stage-label').textContent='02 / YOUR PROJECT WITH WORKX IT';$('#legend-text').textContent='Your business. Our development expertise.';updateNodes();showPerspective('owner');$('[data-person="owner"]').focus({preventScroll:true})}
function closeOutcome(){chooseMoment(current);$('#connect').focus({preventScroll:true})}
function updatePlan(){const p=plans[$('#priority').value];$('#plan-summary').innerHTML=`<h3>${p.title}</h3><ul>${p.items.map(x=>`<li>${x}</li>`).join('')}</ul><p><b>Project inputs</b><br>${p.needs}</p><p><b>Review criteria</b><br>${p.measure}</p>`;$('#plan-status').textContent=''}
function openDialog(id){const dialog=document.getElementById(id);if(!dialog||dialog.tagName!=='DIALOG')return;if(id==='blueprint')updatePlan();dialog.showModal()}
function planText(){const name=$('#business-name').value.trim()||'My cleaning business';const p=plans[$('#priority').value];return `WORKX IT — PROJECT OUTLINE\n${name}\n\n${p.title}\n\nDELIVERY APPROACH\n${p.items.map((v,i)=>`${i+1}. ${v}`).join('\n')}\n\nPROJECT INPUTS\n${p.needs}\n\nREVIEW CRITERIA\n${p.measure}\n\nThis outline supports an initial project discussion. Requirements, deliverables and delivery stages are confirmed through consultation.\n\nWORKX IT\nWebsite development and digital transformation for cleaning businesses.`}
function downloadPlan(){const blob=new Blob([planText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='WORKX-IT-Project-Outline.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#plan-status').textContent='Your project outline is ready to save and discuss.'}
document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>chooseMoment(Number(b.dataset.scenario))));document.querySelectorAll('[data-person]').forEach(b=>b.addEventListener('click',()=>showPerspective(b.dataset.person)));$('#connect').addEventListener('click',connect);$('#reset').addEventListener('click',()=>chooseMoment(current));$('#close-outcome').addEventListener('click',closeOutcome);$('#outcome').addEventListener('keydown',e=>{if(e.key==='Escape'&&connected){e.preventDefault();closeOutcome()}});document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openDialog(b.dataset.open)));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#about-plan').addEventListener('click',()=>{$('#about').close();openDialog('blueprint')});$('#priority').addEventListener('change',updatePlan);$('#download').addEventListener('click',downloadPlan);$('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(planText());$('#plan-status').textContent='Copied. Ready for your conversation with WorkX IT.'}catch{$('#plan-status').textContent='Copy is unavailable in this browser. Use “Save project outline” instead.'}});$('#view-steps').setAttribute('aria-controls','steps-panel');$('#view-steps').addEventListener('click',()=>{const panel=$('#steps-panel');panel.hidden=!panel.hidden;$('#view-steps').setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){$('#steps-list').innerHTML=moments[current].steps.map(x=>`<li><strong>${x[0]}</strong>${x[1]}</li>`).join('');panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}});$('#close-steps').addEventListener('click',()=>{$('#steps-panel').hidden=true;$('#view-steps').setAttribute('aria-expanded','false');$('#view-steps').focus()});chooseMoment(0);
